<div class="page-head"><div><h1>Charts & Analytics</h1><p>Visualize your paper-trading activity.</p></div></div>
<div class="two-col"><div class="card"><div class="card-head"><h2>BTC / USDT</h2></div><div class="card-body"><div class="chart-large"><canvas id="chart1"></canvas></div></div></div><div class="card"><div class="card-head"><h2>Performance Summary</h2></div><div class="card-body"><div class="detail-grid"><div class="detail-item"><span>Total Trades</span><strong><?= (int)$pdo->query("SELECT COUNT(*) FROM transactions")->fetchColumn() ?></strong></div><div class="detail-item"><span>Open Trades</span><strong><?= (int)$pdo->query("SELECT COUNT(*) FROM transactions WHERE status='OPEN'")->fetchColumn() ?></strong></div><div class="detail-item"><span>Total P/L</span><strong class="positive"><?= money((float)$pdo->query("SELECT COALESCE(SUM(profit_loss),0) FROM transactions")->fetchColumn()) ?></strong></div><div class="detail-item"><span>Account</span><strong>Paper</strong></div></div></div></div></div>
<script>
(function(){const c=document.getElementById('chart1'),x=c.getContext('2d');function draw(){const d=devicePixelRatio||1,w=c.clientWidth,h=c.clientHeight;c.width=w*d;c.height=h*d;x.scale(d,d);x.fillStyle='#081a2d';x.fillRect(0,0,w,h);let p=[];for(let i=0;i<45;i++)p.push(100+Math.sin(i/3)*14+i*.8+(Math.random()*7));for(let i=0;i<8;i++){x.strokeStyle='#17314b';x.beginPath();x.moveTo(0,30+i*(h-50)/7);x.lineTo(w,30+i*(h-50)/7);x.stroke()}x.strokeStyle='#42c98a';x.lineWidth=2;x.beginPath();p.forEach((v,i)=>{let xx=12+i*(w-24)/(p.length-1),yy=h-25-(v-85)*2.3;i?x.lineTo(xx,yy):x.moveTo(xx,yy)});x.stroke()}draw();window.addEventListener('resize',draw)})();
</script>
